/**
 * RRT Automations — Build KPI response e-mail
 * Code node · Mode: "Run Once for Each Item"
 *
 * In : $json            -> matched Google Sheets row (recipient lookup)
 *      KoBoToolbox item -> the raw survey submission
 * Out: { email, subject, html }
 *
 * Every field read goes through a null-safe helper, so a question the
 * enumerator skipped can no longer crash the whole execution.
 */

/* ── Config ─────────────────────────────────────────────────────────── */
const HIDE_EMPTY = true;                       // false = print every field, even blanks
const BANNER     = 'https://i.imgur.com/qBBpOGI.jpeg';
const BRAND       = '#1b5e20';   // forest green  — primary: chrome, sales
const ACCENT      = '#a8471a';   // burnt orange  — secondary: payments
const ACCENT_SOFT = '#fdf0e8';
const ACCENT_LINE = '#f0d7c6';
const BRAND_SOFT  = '#e4f1e5';
const BRAND_LINE  = '#cfe3d0';
const INK         = '#1f2a22';
const MUTED       = '#6b7669';
const LINE        = '#e3e9e2';
const SOFT        = '#f2f7f1';
const PAGE        = '#edf1ec';

const k   = $('KoBoToolbox Trigger').item.json;
const row = $json;

/* ── Value helpers ──────────────────────────────────────────────────── */
const val = (p) => {
  const v = k[p];
  return v === undefined || v === null || String(v).trim() === '' ? null : String(v).trim();
};
const num = (p) => {
  const v = val(p);
  if (v === null) return null;
  const n = Number(v.replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const fmt   = (n) => (n === null ? null : n.toLocaleString('en-US'));
const money = (p) => fmt(num(p));
const upper = (p) => { const v = val(p); return v ? v.toUpperCase() : null; };
const tail  = (p) => { const v = val(p); return v ? v.split('_').pop().toUpperCase() : null; };
const multi = (p) => { const v = val(p); return v ? v.split(/\s+/).map((s) => s.replace(/_/g, ' ').toUpperCase()) : []; };
const yn    = (p) => { const v = val(p); return v ? v.replace(/_/g, ' ').toUpperCase() : null; };
const esc   = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const asDate = (s, withTime = false) => {
  if (!s) return null;
  const d = new Date(s);
  if (isNaN(d.getTime())) return s;
  const date = d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  return withTime ? `${date}, ${d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}` : date;
};

/* ── HTML building blocks ───────────────────────────────────────────── */
const F = 'Arial,Helvetica,sans-serif';

const line = (label, value, opt = {}) => {
  const blank = value === null || value === undefined || value === '';
  if (blank && HIDE_EMPTY && !opt.always) return '';
  const shown = blank ? '&mdash;' : (opt.raw ? value : esc(value));
  // opt.strong = subtotal row: label darkens from muted to ink, both sides bold.
  const lw = opt.strong ? '700' : '400';
  const lc = opt.strong ? INK : MUTED;
  const vw = opt.strong ? '700' : '600';
  return `<tr>
  <td style="padding:9px 0;border-bottom:1px solid ${LINE};font:${lw} 14px/1.45 ${F};color:${lc};">${esc(label)}</td>
  <td align="right" style="padding:9px 0;border-bottom:1px solid ${LINE};font:${vw} 14px/1.45 ${F};color:${INK};">${shown}</td>
</tr>`;
};

const cash = (label, path, opt = {}) => {
  const n = num(path);
  if ((n === null || (n === 0 && opt.hideZero !== false)) && HIDE_EMPTY) return '';
  return line(label, fmt(n === null ? 0 : n), opt);
};

const badge = (text, tone) => {
  const c = tone === 'good' ? ['#e4f1e5', '#1b5e20']
          : tone === 'bad'  ? ['#fdecec', '#9b1c1c']
          :                   ['#edf0ec', '#4a5546'];
  return `<span style="display:inline-block;padding:3px 11px;border-radius:100px;background:${c[0]};color:${c[1]};font:700 12px/1.5 ${F};">${esc(text)}</span>`;
};

const total = (label, value, tone) => {
  if (value === null || value === undefined) return '';
  const solid = tone === 'primary' || tone === 'secondary';
  const bg = tone === 'primary' ? BRAND : tone === 'secondary' ? ACCENT : SOFT;
  const fg = solid ? '#ffffff' : BRAND;
  const lb = solid ? 'rgba(255,255,255,.75)' : MUTED;
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:14px;background:${bg};border-radius:8px;">
  <tr>
    <td style="padding:14px 16px;font:700 12px/1.4 ${F};letter-spacing:.07em;text-transform:uppercase;color:${lb};">${esc(label)}</td>
    <td align="right" style="padding:14px 16px;font:700 20px/1.2 ${F};color:${fg};white-space:nowrap;">${esc(value)}</td>
  </tr>
</table>`;
};

const block = (title, body, tone) => {
  if (!body || !body.trim()) return '';
  const c = tone === 'secondary' ? ACCENT : BRAND;
  return `<tr><td style="padding:28px 28px 0;">
  <div style="padding-bottom:9px;border-bottom:2px solid ${c};font:700 12px/1 ${F};letter-spacing:.12em;text-transform:uppercase;color:${c};">${esc(title)}</div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${body}</table>
</td></tr>`;
};

/* ── Section: header meta ───────────────────────────────────────────── */
const district = upper('group_ct1fu44/district');
const pod      = upper('group_ct1fu44/Pod');
const role     = tail('group_ct1fu44/Role');
const others   = upper('group_ct1fu44/others');
const repDate  = asDate(val('group_ct1fu45/Date'));

const metaCell = (label, value) => (!value && HIDE_EMPTY ? '' : `
  <td width="25%" style="padding:0 8px 0 0;vertical-align:top;">
    <div style="font:700 10px/1.4 ${F};letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.62);">${esc(label)}</div>
    <div style="font:700 15px/1.4 ${F};color:#ffffff;">${esc(value || '—')}</div>
  </td>`);

const metaRow = [
  metaCell('District', district),
  metaCell('POD', pod),
  metaCell('Role', role),
  metaCell('Date', repDate),
].filter(Boolean).join('');

/* ── Section: sales ─────────────────────────────────────────────────── */
const salesBody = [
  cash('Sales by FTO',       'group_ct1fu45/ftosales'),
  cash('Sales by VSO',       'group_ct1fu45/vsosales'),
  cash('Sales by FM',        'group_ct1fu45/fmsales'),
  cash('Sales by FO',        'group_ct1fu45/fosales'),
  cash('Sales by MO',        'group_ct1fu45/mosales'),
  cash('Sales by Referrals', 'group_ct1fu45/referalsales'),
].join('');

const odoo     = yn('group_ct1fu45/odoo');
const odooTone = odoo ? (/^(YES|Y|TRUE|1)$/.test(odoo) ? 'good' : 'bad') : 'neutral';
const totalSales = money('group_ct1fu45/todaytotal');

const salesExtra = [
  salesBody ? line('Posted on Odoo', odoo ? badge(odoo, odooTone) : null, { raw: true }) : '',
].join('');

/* ── Section: customers ─────────────────────────────────────────────── */
const customersBody = [
  cash('Returning customers', 'group_ct1fu46/returning'),
  cash('New customers',       'group_ct1fu46/new'),
  cash('Total customers',     'group_ct1fu46/clients', { strong: true }),
  cash('Farmers aggregated',  'group_ct1fu46/Farmers'),
].join('');

/* ── Section: split / shared sales ──────────────────────────────────── */
const anySplit    = yn('group_ct1fu47/Split');
const splitIsYes  = anySplit ? /^(YES|Y|TRUE|1)$/.test(anySplit) : false;
const splitRows   = [];

for (let i = 1; i <= 10; i++) {
  const shop = val(`group_ct1fu47/shop${i}`);
  const amt  = num(`group_ct1fu47/split${i}`);
  if (!shop && (amt === null || amt === 0)) continue;
  splitRows.push(line(shop ? shop.replace(/_/g, ' ') : `Shop ${i}`, fmt(amt === null ? 0 : amt)));
}

let splitBody = '';
if (splitIsYes || splitRows.length) {
  splitBody = [
    line('Any split sale', anySplit ? badge(anySplit, splitIsYes ? 'good' : 'neutral') : null, { raw: true }),
    cash('Number of split sales', 'group_ct1fu47/split_count', { strong: true }),
    splitRows.join(''),
    cash('Total split',            'group_ct1fu47/totalsplit', { strong: true }),
    cash('Total from your shop',   'group_ct1fu47/self'),
  ].join('');
}
const splitTotal = money('group_ct1fu47/shared_self');

/* ── Section: payments ──────────────────────────────────────────────── */
const payTypes = multi('group_ct1fu48/payment_type');
const vchTypes = multi('group_ct1fu48/Voucher');

const chips = (arr, tone) => {
  if (!arr.length) return null;
  const [bg, bd, fg] = tone === 'brand'
    ? [BRAND_SOFT, BRAND_LINE, BRAND]
    : [ACCENT_SOFT, ACCENT_LINE, ACCENT];
  return arr.map((t) => `<span style="display:inline-block;margin:0 5px 5px 0;padding:4px 10px;border-radius:5px;background:${bg};border:1px solid ${bd};font:600 12px/1.5 ${F};color:${fg};">${esc(t)}</span>`).join(' ');
};

const vouchers = [
  ['Bank',                   'group_ct1fu48/bank'],
  ['Staff voucher',          'group_ct1fu48/staff'],
  ['Damaged bags voucher',   'group_ct1fu48/damaged_value'],
  ['Bulk purchase voucher',  'group_ct1fu48/bulk_value'],
  ['Shop setup voucher',     'group_ct1fu48/shop_value'],
  ['OAF voucher',            'group_ct1fu48/oaf_value'],
  ['Promo purchase voucher', 'group_ct1fu48/promo_value'],
  ['Incentive voucher',      'group_ct1fu48/incentive_value'],
  ['Insurance payout',       'group_ct1fu48/payout_value'],
  ['FOPS voucher',           'group_ct1fu48/fops_value'],
  ['Bundle promo voucher',   'group_ct1fu48/bundle_value'],
];

const paymentBody = [
  line('Payment type', chips(payTypes), { raw: true }),
  line('Voucher type', chips(vchTypes, 'brand'), { raw: true }),
  vouchers.map(([label, path]) => cash(label, path)).join(''),
].join('');

const totalPayment = money('group_ct1fu48/totalpayment');

/* ── Section: unposted ──────────────────────────────────────────────── */
const hasUnposted   = yn('group_ct1fu49/Do_You_Have_Unposted_Amounts');
const unpostedIsYes = hasUnposted ? /^(YES|Y|TRUE|1)$/.test(hasUnposted) : false;
const comment       = val('group_ct1fu49/Any_Comment');

const unpostedBody = [
  line('Any unposted amount', hasUnposted ? badge(hasUnposted, unpostedIsYes ? 'bad' : 'good') : null, { raw: true }),
  cash('Unposted amount', 'group_ct1fu49/How_Much_Unposted_Amount_do_you_have'),
  comment
    ? `<tr><td colspan="2" style="padding:12px 0 0;">
         <div style="font:700 10px/1.4 ${F};letter-spacing:.1em;text-transform:uppercase;color:${MUTED};padding-bottom:5px;">Comments</div>
         <div style="padding:12px 14px;background:${SOFT};border-left:3px solid ${BRAND};border-radius:0 6px 6px 0;font:400 14px/1.55 ${F};color:${INK};">${esc(comment)}</div>
       </td></tr>`
    : '',
].join('');

/* ── Recipient + subject ────────────────────────────────────────────── */
const email = String(row.col_2 || row.Email || row.email || '').trim();
if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
  throw new Error(
    `No valid recipient e-mail for KoBo user "${k._submitted_by}". ` +
    `Check the "Kobo Username" -> "col_2" mapping in Sheet16. Got: "${email}"`
  );
}

const subject = ['Cash Sales KPI Response', pod, repDate].filter(Boolean).join(' · ');
const preheader = [
  totalSales ? `Total sales ${totalSales}` : null,
  totalPayment ? `Payments ${totalPayment}` : null,
  unpostedIsYes ? 'Unposted amount flagged' : null,
].filter(Boolean).join(' · ');

const submitted = asDate(val('_submission_time'), true) || asDate(k._submission_time, true);

/* ── Assemble ───────────────────────────────────────────────────────── */
const html = `<!DOCTYPE html>
<html lang="en"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light only">
<meta name="supported-color-schemes" content="light only">
<title>${esc(subject)}</title>
<style>
  body{margin:0;padding:0;width:100%!important;-webkit-text-size-adjust:100%;}
  table{border-collapse:collapse;}
  img{border:0;outline:none;text-decoration:none;-ms-interpolation-mode:bicubic;}
  a{color:${BRAND};}
  @media only screen and (max-width:620px){
    .card{width:100%!important;border-radius:0!important;}
    .pad{padding-left:18px!important;padding-right:18px!important;}
    .meta td{display:block!important;width:100%!important;padding:0 0 12px!important;}
  }
</style>
</head>
<body style="margin:0;padding:0;background:${PAGE};">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;font-size:1px;line-height:1px;color:${PAGE};">${esc(preheader)}&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;</div>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${PAGE};">
<tr><td align="center" style="padding:24px 12px;">

  <table role="presentation" class="card" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 1px 3px rgba(16,24,40,.08);">

    <tr><td style="font-size:0;line-height:0;">
      <img src="${BANNER}" alt="" width="600" style="width:100%;max-width:600px;height:auto;display:block;">
    </td></tr>

    <tr><td class="pad" style="padding:26px 28px 22px;background:${BRAND};">
      <div style="font:700 20px/1.3 ${F};color:#ffffff;">Your KPI response</div>
      <div style="font:400 13px/1.5 ${F};color:rgba(255,255,255,.72);padding-top:4px;">Cash sales submission received${submitted ? ` &middot; ${esc(submitted)}` : ''}</div>
      ${metaRow ? `<table role="presentation" class="meta" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:20px;padding-top:18px;border-top:1px solid rgba(255,255,255,.22);"><tr>${metaRow}</tr></table>` : ''}
      ${others ? `<div style="margin-top:14px;font:400 12px/1.5 ${F};color:rgba(255,255,255,.72);">Others: <span style="color:#fff;font-weight:600;">${esc(others)}</span></div>` : ''}
    </td></tr>

    ${block('Sales', salesBody + salesExtra)}
    ${totalSales ? `<tr><td class="pad" style="padding:0 28px;">${total('Total sales today', totalSales, 'primary')}</td></tr>` : ''}

    ${block('Customers', customersBody)}

    ${block('Shared / split sales', splitBody)}
    ${splitBody && splitTotal ? `<tr><td class="pad" style="padding:0 28px;">${total('Total (split + own shop)', splitTotal)}</td></tr>` : ''}

    ${block('Payment details', paymentBody, 'secondary')}
    ${totalPayment ? `<tr><td class="pad" style="padding:0 28px;">${total('Total payment', totalPayment, 'secondary')}</td></tr>` : ''}

    ${block('Unposted amount', unpostedBody)}

    <tr><td class="pad" style="padding:30px 28px 26px;">
      <div style="border-top:1px solid ${LINE};padding-top:16px;font:400 12px/1.6 ${F};color:${MUTED};">
        Automated confirmation of your cash sales KPI submission${k._submitted_by ? ` from <strong style="color:${INK};">${esc(k._submitted_by)}</strong>` : ''}.<br>
        Please do not reply to this e-mail &mdash; contact your district lead if any figure above looks wrong.
      </div>
    </td></tr>

  </table>

</td></tr>
</table>
</body></html>`;

return { json: { email, subject, html } };
